package com.gwangseong.run;

import android.Manifest;import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.view.View;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.core.app.ActivityCompat;import java.util.Locale;

public class MainActivity extends AppCompatActivity {
    private EditText name,email,password,phoneLast4; private TextView status,distance,stepsView,time,coins;
    private Button loginButton,registerButton,resetButton,logoutButton,startButton,stopButton,submitButton;
    private LinearLayout authPanel,runPanel; private android.content.SharedPreferences prefs; private int steps;private long seconds; private String mode="login";
    @Override protected void onCreate(Bundle state){super.onCreate(state);setContentView(R.layout.activity_main);
        prefs=getSharedPreferences("run",MODE_PRIVATE);
        name=findViewById(R.id.name);email=findViewById(R.id.email);password=findViewById(R.id.password);phoneLast4=findViewById(R.id.phoneLast4);status=findViewById(R.id.status);
        distance=findViewById(R.id.distance);stepsView=findViewById(R.id.steps);time=findViewById(R.id.time);coins=findViewById(R.id.coins);authPanel=findViewById(R.id.authPanel);runPanel=findViewById(R.id.runPanel);
        loginButton=findViewById(R.id.loginButton);registerButton=findViewById(R.id.registerButton);resetButton=findViewById(R.id.resetButton);logoutButton=findViewById(R.id.logoutButton);startButton=findViewById(R.id.startButton);stopButton=findViewById(R.id.stopButton);submitButton=findViewById(R.id.submitButton);
        email.setText(prefs.getString("email","")); steps=prefs.getInt("lastSteps",0);seconds=prefs.getLong("lastSeconds",0);
        loginButton.setOnClickListener(v->primaryAction());registerButton.setOnClickListener(v->showMode(mode.equals("register")?"login":"register"));resetButton.setOnClickListener(v->showMode(mode.equals("reset")?"login":"reset"));logoutButton.setOnClickListener(v->logout());
        startButton.setOnClickListener(v->startRun());stopButton.setOnClickListener(v->stopRun());submitButton.setOnClickListener(v->submit());
        boolean running=prefs.getBoolean("running",false);startButton.setEnabled(!running);stopButton.setEnabled(running);submitButton.setEnabled(!running&&steps>0);showSignedIn(!prefs.getString("token","").isEmpty());render();requestPermissions();
    }
    private void showMode(String next){mode=next;boolean register=mode.equals("register"),reset=mode.equals("reset");name.setVisibility(register?View.VISIBLE:View.GONE);phoneLast4.setVisibility(register||reset?View.VISIBLE:View.GONE);loginButton.setText(register?"가입하고 시작하기":reset?"새 비밀번호로 변경":"로그인");registerButton.setText(register?"로그인으로 돌아가기":"회원가입");resetButton.setText(reset?"로그인으로 돌아가기":"비밀번호 찾기");status.setText(register?"앱에서 바로 회원가입할 수 있어요.":reset?"가입한 이메일과 휴대폰 뒤 4자리를 입력해주세요.":"로그인해주세요.");}
    private void primaryAction(){String mail=email.getText().toString().trim().toLowerCase(Locale.KOREA),pass=password.getText().toString(),phone=phoneLast4.getText().toString().trim(),person=name.getText().toString().trim();if(!mail.contains("@")||pass.length()<6){status.setText("이메일과 비밀번호 6자리 이상을 확인해주세요.");return;}loginButton.setEnabled(false);status.setText("확인 중…");ApiClient.Callback callback=(ok,msg,data)->runOnUiThread(()->{loginButton.setEnabled(true);status.setText(msg);if(ok&&!mode.equals("reset")){prefs.edit().putString("token",data.optString("token")).putString("email",mail).putString("name",data.optString("name","회원")).putString("memberNo",data.optString("memberNo","")).apply();showSignedIn(true);}else if(ok){password.setText("");showMode("login");}});if(mode.equals("register"))ApiClient.register(person,mail,pass,phone,callback);else if(mode.equals("reset"))ApiClient.resetPassword(mail,phone,pass,callback);else ApiClient.login(mail,pass,callback);}
    private void showSignedIn(boolean signedIn){authPanel.setVisibility(signedIn?View.GONE:View.VISIBLE);runPanel.setVisibility(signedIn?View.VISIBLE:View.GONE);if(signedIn)status.setText(prefs.getString("name","회원")+"님 · 로그인됨");}
    private void logout(){prefs.edit().remove("token").apply();showSignedIn(false);showMode("login");}
    private void requestPermissions(){if(Build.VERSION.SDK_INT>=23&&ActivityCompat.checkSelfPermission(this,Manifest.permission.ACTIVITY_RECOGNITION)!=PackageManager.PERMISSION_GRANTED)ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.ACTIVITY_RECOGNITION},7);if(Build.VERSION.SDK_INT>=33)ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.POST_NOTIFICATIONS},8);}
    private void startRun(){Intent i=new Intent(this,RunService.class).setAction(RunService.ACTION_START);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);steps=0;seconds=0;startButton.setEnabled(false);stopButton.setEnabled(true);submitButton.setEnabled(false);status.setText("측정 중이에요.");render();}
    private void stopRun(){startService(new Intent(this,RunService.class).setAction(RunService.ACTION_STOP));steps=prefs.getInt("lastSteps",steps);seconds=prefs.getLong("lastSeconds",seconds);startButton.setEnabled(true);stopButton.setEnabled(false);submitButton.setEnabled(steps>0);status.setText("측정 완료! 관리자에게 전송해주세요.");render();}
    private void submit(){if(steps<1||seconds<10){status.setText("10초 이상 측정한 기록만 전송할 수 있어요.");return;}submitButton.setEnabled(false);status.setText("관리자에게 전송 중…");double km=steps*0.0007;ApiClient.submit(prefs.getString("token",""),steps,seconds,km,(ok,msg,data)->runOnUiThread(()->{status.setText(msg);if(ok){steps=0;seconds=0;prefs.edit().putInt("lastSteps",0).putLong("lastSeconds",0).apply();render();}else submitButton.setEnabled(true);}));}
    private void render(){distance.setText(String.format(Locale.KOREA,"%.2f km",steps*0.0007));stepsView.setText(steps+" 걸음");time.setText(String.format(Locale.KOREA,"%02d:%02d",seconds/60,seconds%60));coins.setText(((int)Math.floor(steps*0.0007*10))+" C");}
    private final BroadcastReceiver updates=new BroadcastReceiver(){@Override public void onReceive(Context c,Intent i){steps=i.getIntExtra("steps",0);seconds=i.getLongExtra("seconds",0);render();}};
    @Override protected void onStart(){super.onStart();IntentFilter filter=new IntentFilter(RunService.ACTION_UPDATE);if(Build.VERSION.SDK_INT>=33)registerReceiver(updates,filter,RECEIVER_NOT_EXPORTED);else registerReceiver(updates,filter);}
    @Override protected void onStop(){try{unregisterReceiver(updates);}catch(Exception ignored){}super.onStop();}
}
